def to_zone(zone: TimezoneLike) -> ZoneInfo:
    """Resolve ``zone`` to a :class:`ZoneInfo` instance.

    Accepts either an IANA name or an already-constructed ``ZoneInfo``.
    Raises :class:`ZoneInfoNotFoundError` for unknown names.
    """
    if isinstance(zone, ZoneInfo):
        return zone
    return ZoneInfo(zone)


def _zone_name(zone: TimezoneLike) -> str:
    return zone if isinstance(zone, str) else zone.key

